-- ============================================================
-- SIMBAKES — PANDUAN ADMIN & OPERATOR (HARDENING BACKEND OPSIONAL)
-- ============================================================
-- Tujuan:
--   Memindahkan sumber data Panduan Admin & Operator ke DATABASE
--   sehingga isi panduan hanya bisa diambil lewat RPC yang tervalidasi
--   RLS (role admin/operator pada sesi asli aplikasi).
--
-- Setelah SQL ini dijalankan:
--   1. js/16-panduan.js otomatis memakai jalur RPC (utama).
--   2. Berkas statis panduan/admin-data.js tidak dipakai lagi dan
--      BOLEH DIHAPUS dari hosting untuk penguncian maksimal.
--
-- Cara pakai:
--   Supabase Dashboard -> SQL Editor -> New query
--   -> Paste SELURUH isi file ini -> Run
--
-- Aman dijalankan berulang (create or replace).
-- ============================================================

drop function if exists public.app_get_panduan_admin();

create or replace function public.app_get_panduan_admin()
returns jsonb
language plpgsql stable security definer
set search_path = public, extensions
as $fn$
begin
    -- WAJIB: sesi admin asli dengan role superadmin/operator/admin.
    -- 'write' di app_is_valid_session = superadmin + operator + admin.
    if not public.app_is_valid_session('write') then
        return null;   -- ditolak di server (bukan hanya di browser)
    end if;
    return $pb${"id":"admin","judul":"Panduan Admin & Operator","judulPanjang":"Panduan Penggunaan SIMBAKES untuk Admin & Operator","deskripsi":"Panduan pengelolaan aplikasi bagi Admin dan Operator.","edisi":"Edisi 2026","palet":{"primary":"#2a5298","primaryD":"#1a365d","accent":"#2a5298"},"css":".pbb{\n  --primary:#2a5298; --primary-d:#1a365d; --primary-l:#7d9cc7; --accent:#2a5298;\n  --header-fill:#3f5876; --page-bg:#f4f5f7; --section-bg:#eff1f4; --card-bg:#e8ecf2;\n  --stripe:#f0f3f6; --border:#ccd5e0; --text:#1a2230; --muted:#5d6b7e;\n  --success:#3d7a52; --success-bg:#e9f3ec; --warning:#8a6d3b; --warning-bg:#f4efe3;\n  --error:#91443c; --error-bg:#f5e9e7; --info:#4a6d8c; --info-bg:#e9eff5;\n}\n.pbb,.pbb *{ box-sizing:border-box; }\n.pbb p, .pbb td, .pbb li{ line-break:strict; text-align:justify; hyphens:auto; }\n.pbb /* ============ FRONT PAGE ============ */\n.frontpage{ width:794px; height:1123px; position:relative; background:var(--page-bg);\n  break-after:page; overflow:hidden; border:none; }\n.pbb .cov-l1{ position:absolute; inset:0; overflow:hidden; z-index:1; }\n.pbb .cov-grid{ position:absolute; inset:0;\n  background-image:repeating-linear-gradient(0deg,rgba(42,82,152,.05) 0 .6px,transparent .6px 52px),\n                   repeating-linear-gradient(90deg,rgba(42,82,152,.05) 0 .6px,transparent .6px 52px); }\n.pbb .cov-circles{ position:absolute; right:0; bottom:0; width:430px; height:430px; }\n.pbb .cov-l2{ position:absolute; inset:0; z-index:2; }\n.pbb .cov-anchor{ position:absolute; left:95px; top:112px; bottom:112px; width:6px; background:var(--accent); }\n.pbb .cov-l3{ position:absolute; inset:0; z-index:3; }\n.pbb .cov-kicker{ position:absolute; left:175px; top:150px; font-size:12.5px; font-weight:600;\n  letter-spacing:4px; color:var(--primary-d); opacity:.62; text-transform:uppercase; }\n.pbb .cov-hero{ position:absolute; left:175px; top:236px; font-family:'Plus Jakarta Sans','Inter',sans-serif;\n  font-size:66px; font-weight:800; letter-spacing:1px; color:var(--text); line-height:1.1; }\n.pbb .cov-rule{ position:absolute; left:178px; top:352px; width:66px; height:5px; background:var(--accent); border-radius:3px; }\n.pbb .cov-sub{ position:absolute; left:175px; top:404px; font-family:'Plus Jakarta Sans','Inter',sans-serif;\n  font-size:26px; font-weight:700; color:var(--primary-d); line-height:1.3; max-width:520px; }\n.pbb .cov-sum{ position:absolute; left:175px; top:560px; font-size:15.5px; line-height:1.75;\n  color:var(--muted); max-width:480px; text-align:left; }\n.pbb .cov-chips{ position:absolute; left:175px; top:756px; display:flex; gap:10px; flex-wrap:wrap; max-width:540px; }\n.pbb .cov-chip{ border:1px solid var(--border); background:#fff; border-radius:999px;\n  padding:6px 16px; font-size:12px; font-weight:600; color:var(--primary-d); }\n.pbb .cov-meta{ position:absolute; left:175px; top:852px; font-size:14px; color:var(--text); }\n.pbb .cov-meta b{ font-weight:700; color:var(--primary-d); }\n.pbb .cov-meta .sub{ display:block; margin-top:4px; font-size:12.5px; color:var(--muted); }\n.pbb .cov-foot{ position:absolute; left:175px; right:60px; bottom:72px; display:flex;\n  justify-content:space-between; align-items:baseline; font-size:11.5px; letter-spacing:1.5px;\n  color:var(--muted); text-transform:uppercase; }\n.pbb .cov-foot b{ color:var(--primary-d); font-weight:700; }\n.pbb /* ============ TOC PAGE ============ */\n.toc-page{ width:794px; height:1123px; break-after:page; background:#fff; position:relative;\n  padding:72px 96px 48px 96px; }\n.pbb .toc-kicker{ font-size:11.5px; letter-spacing:3px; font-weight:700; color:var(--accent); text-transform:uppercase; }\n.pbb .toc-title{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:32px; font-weight:800;\n  color:var(--text); margin:6px 0 4px 0; }\n.pbb .toc-sub{ font-size:13px; color:var(--muted); margin-bottom:26px; text-align:left; }\n.pbb .titem{ display:flex; gap:14px; padding:6.5px 0; border-bottom:1px dashed var(--border); }\n.pbb .titem:last-of-type{ border-bottom:none; }\n.pbb .tnum{ width:30px; flex:0 0 30px; font-weight:800; color:var(--accent); font-size:13px; }\n.pbb .tblock{ flex:1; min-width:0; }\n.pbb .trow{ display:flex; align-items:baseline; }\n.pbb .ttl{ font-weight:600; font-size:14px; color:var(--text); }\n.pbb .tline{ flex:1; border-bottom:1px dotted var(--border); margin:0 10px; transform:translateY(-3px); min-width:24px; }\n.pbb .tpage{ font-weight:700; color:var(--primary); font-variant-numeric:tabular-nums; font-size:13px; }\n.pbb .tdesc{ display:block; font-size:11.5px; color:var(--muted); margin-top:1px; text-align:left; }\n.pbb .toc-note{ margin-top:18px; border:1px solid var(--border); background:var(--section-bg);\n  border-radius:12px; padding:12px 16px; font-size:12px; color:var(--text); }\n.pbb .toc-note b{ color:var(--primary-d); }\n.pbb /* ============ MAIN CONTENT ============ */\n.main-content{ padding:58px 64px 46px 64px; background:#fff; }\n.pbb .chapter-header{ break-after:avoid; break-inside:avoid; margin-top:28px; }\n.pbb .chapter-header.first{ margin-top:0; }\n.pbb .ch-tag{ font-size:11px; letter-spacing:2.5px; font-weight:800; color:var(--accent); text-transform:uppercase; }\n.pbb .ch-title{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:25px; font-weight:800;\n  color:var(--text); margin:3px 0 0 0; line-height:1.25; }\n.pbb .ch-div{ display:flex; align-items:center; gap:0; margin:10px 0 14px 0; }\n.pbb .ch-div .bar{ width:52px; height:3.5px; background:var(--accent); border-radius:2px; }\n.pbb .ch-div .hair{ flex:1; height:1px; background:var(--border); }\n.pbb .lead{ font-size:14.5px; color:var(--muted); margin:0 0 10px 0; }\n.pbb h3.sec{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:16px; font-weight:700;\n  color:var(--primary-d); margin:18px 0 8px 0; break-after:avoid; page-break-after:avoid; }\n.pbb p{ margin:0 0 10px 0; }\n.pbb /* callout */\n.callout{ border-radius:10px; padding:11px 15px 11px 16px; margin:12px 0; break-inside:avoid;\n  page-break-inside:avoid; border-left:4px solid; font-size:13px; }\n.pbb .callout .co-label{ font-size:10px; letter-spacing:1.8px; font-weight:800; display:block; margin-bottom:3px; text-transform:uppercase; }\n.pbb .callout p{ margin:0; }\n.pbb .callout.tip{ background:var(--success-bg); border-color:var(--success); color:#275137; }\n.pbb .callout.tip .co-label{ color:var(--success); }\n.pbb .callout.warn{ background:var(--warning-bg); border-color:var(--warning); color:#6d5628; }\n.pbb .callout.warn .co-label{ color:var(--warning); }\n.pbb .callout.danger{ background:var(--error-bg); border-color:var(--error); color:#753630; }\n.pbb .callout.danger .co-label{ color:var(--error); }\n.pbb .callout.info{ background:var(--info-bg); border-color:var(--info); color:#3a5570; }\n.pbb .callout.info .co-label{ color:var(--info); }\n.pbb /* steps */\n.steps{ list-style:none; margin:10px 0; padding:0; counter-reset:step; }\n.pbb .steps li{ position:relative; padding:0 0 6px 42px; margin-bottom:8px; counter-increment:step;\n  break-inside:avoid; page-break-inside:avoid; }\n.pbb .steps li::before{ content:counter(step,decimal-leading-zero); position:absolute; left:0; top:1px;\n  width:29px; height:29px; border-radius:9px; background:var(--primary); color:#fff; font-weight:700;\n  font-size:12px; display:flex; align-items:center; justify-content:center; }\n.pbb .steps b.st{ display:block; font-weight:700; color:var(--text); margin-bottom:1px; }\n.pbb .steps p{ margin:0 0 4px 0; font-size:13.5px; }\n.pbb /* tables */\ntable.data{ width:100%; border-collapse:collapse; margin:12px 0; font-size:12.8px; }\n.pbb table.data thead{ display:table-header-group; }\n.pbb table.data thead th{ background:var(--header-fill); color:#fff; text-align:left; padding:8px 12px;\n  font-weight:600; font-size:11.8px; letter-spacing:.4px; }\n.pbb table.data thead th:first-child{ border-radius:8px 0 0 0; }\n.pbb table.data thead th:last-child{ border-radius:0 8px 0 0; }\n.pbb table.data tbody td{ padding:7.5px 12px; border-bottom:1px solid var(--border); vertical-align:top; }\n.pbb table.data tbody tr{ break-inside:avoid; page-break-inside:avoid; }\n.pbb table.data tbody tr:nth-child(odd){ background:var(--stripe); }\n.pbb table.data ul{ margin:0; padding-left:16px; }\n.pbb table.data p{ margin:0; }\n.pbb /* badges */\n.badge{ display:inline-block; padding:1.5px 10px; border-radius:999px; font-size:11px; font-weight:700; white-space:nowrap; }\n.pbb .b-verify{ background:var(--info-bg); color:var(--info); }\n.pbb .b-ok{ background:var(--success-bg); color:var(--success); }\n.pbb .b-no{ background:var(--error-bg); color:var(--error); }\n.pbb .b-rev{ background:var(--warning-bg); color:var(--warning); }\n.pbb .b-off{ background:#e8eaec; color:#57616d; }\n.pbb /* flow */\n.flow{ display:flex; flex-wrap:wrap; gap:10px; margin:14px 0 10px 0; max-width:100%; }\n.pbb .fstep{ flex:1 1 128px; min-width:118px; max-width:100%; background:var(--card-bg);\n  border:1px solid var(--border); border-radius:11px; padding:10px 12px;\n  break-inside:avoid; page-break-inside:avoid; overflow-wrap:break-word; }\n.pbb .fstep .fn{ font-size:10px; font-weight:800; letter-spacing:1.5px; color:var(--accent); }\n.pbb .fstep .ft{ font-weight:700; font-size:12.6px; margin-top:2px; color:var(--text); }\n.pbb .fstep .fd{ font-size:11px; color:var(--muted); margin-top:2px; line-height:1.5; text-align:left; }\n.pbb /* menu cards */\n.cards3{ display:grid; grid-template-columns:repeat(3,1fr); gap:12px; margin:12px 0; }\n.pbb .cards2{ display:grid; grid-template-columns:repeat(2,1fr); gap:12px; margin:12px 0; }\n.pbb .mcard{ border:1px solid var(--border); border-radius:12px; padding:13px 15px; background:#fff;\n  break-inside:avoid; page-break-inside:avoid; }\n.pbb .mcard .mc-ico{ width:34px; height:34px; border-radius:10px; background:var(--card-bg);\n  color:var(--primary-d); font-weight:800; font-size:15px; display:flex; align-items:center;\n  justify-content:center; margin-bottom:8px; font-family:'Plus Jakarta Sans','Inter',sans-serif; }\n.pbb .mcard .mc-t{ font-weight:700; font-size:13.5px; color:var(--text); margin-bottom:3px; }\n.pbb .mcard .mc-d{ font-size:12px; color:var(--muted); line-height:1.55; text-align:left; }\n.pbb /* misc */\n.hl{ background:var(--card-bg); padding:0 5px; border-radius:5px; font-weight:600; color:var(--primary-d); }\n.pbb kbd{ font-family:'Inter',monospace; background:var(--section-bg); border:1px solid var(--border);\n  border-radius:6px; padding:1px 7px; font-size:12px; font-weight:600; color:var(--primary-d); }\n.pbb .small{ font-size:12px; color:var(--muted); }\n.pbb ul.plain{ margin:6px 0 10px 0; padding-left:20px; }\n.pbb ul.plain li{ margin-bottom:4px; break-inside:avoid; }\n.pbb /* ============ ENDING ============ */\n.ending{ width:794px; height:1123px; break-before:page; page-break-before:always;\n  background:var(--page-bg); position:relative; overflow:hidden; }\n.pbb .end-frame{ position:absolute; inset:56px 44px; border:1.5px solid var(--border); border-radius:4px; }\n.pbb .end-inner{ position:absolute; inset:56px 44px; display:flex; flex-direction:column;\n  align-items:center; justify-content:center; text-align:center; padding:0 90px; }\n.pbb .end-logo{ width:58px; height:58px; border-radius:16px; background:var(--primary); color:#fff;\n  font-family:'Plus Jakarta Sans','Inter',sans-serif; font-weight:800; font-size:22px;\n  display:flex; align-items:center; justify-content:center; margin-bottom:22px; }\n.pbb .end-title{ font-family:'Plus Jakarta Sans','Inter',sans-serif; font-size:27px; font-weight:800; color:var(--text); margin-bottom:12px; }\n.pbb .end-text{ font-size:14px; color:var(--muted); line-height:1.8; max-width:470px; text-align:center; }\n.pbb .end-contact{ margin-top:30px; display:flex; gap:12px; }\n.pbb .end-cbox{ border:1px solid var(--border); background:#fff; border-radius:12px; padding:13px 20px; text-align:left; }\n.pbb .end-cbox .l{ font-size:10.5px; letter-spacing:1.5px; font-weight:800; color:var(--accent); text-transform:uppercase; }\n.pbb .end-cbox .n{ font-weight:700; font-size:14px; color:var(--text); margin-top:2px; }\n.pbb .end-cbox .p{ font-size:12.5px; color:var(--muted); }\n.pbb .end-foot{ position:absolute; bottom:88px; left:90px; right:90px; text-align:center;\n  font-size:11px; letter-spacing:1.2px; color:var(--muted); text-transform:uppercase; }","cover":"<div class=\"frontpage\">\n  <div class=\"cov-l1\">\n    <div class=\"cov-grid\"></div>\n    <svg class=\"cov-circles\" viewBox=\"0 0 430 430\" fill=\"none\">\n      <circle cx=\"285\" cy=\"285\" r=\"200\" stroke=\"#2a5298\" stroke-width=\"0.7\" opacity=\"0.14\"/>\n      <circle cx=\"315\" cy=\"305\" r=\"200\" stroke=\"#2a5298\" stroke-width=\"0.7\" opacity=\"0.22\"/>\n      <circle cx=\"345\" cy=\"325\" r=\"200\" stroke=\"#2a5298\" stroke-width=\"0.7\" opacity=\"0.32\"/>\n      <circle cx=\"392\" cy=\"60\" r=\"7\" fill=\"#2a5298\" opacity=\"0.5\"/>\n      <circle cx=\"365\" cy=\"90\" r=\"3\" fill=\"#2a5298\" opacity=\"0.3\"/>\n    </svg>\n  </div>\n  <div class=\"cov-l2\">\n    <div class=\"cov-anchor\"></div>\n  </div>\n  <div class=\"cov-l3\">\n    <div class=\"cov-kicker\">Buku Panduan Pengguna &middot; Edisi Admin &amp; Operator</div>\n    <div class=\"cov-hero\">SIMBAKES</div>\n    <div class=\"cov-rule\"></div>\n    <div class=\"cov-sub\">Panduan Penggunaan<br>untuk Admin &amp; Operator</div>\n    <div class=\"cov-sum\">Sistem Informasi Manajemen Beasiswa Tematik Bidang Kesehatan\n      Pemerintah Kabupaten Kutai Kartanegara. Buku ini memandu tim Dinas Kesehatan dalam\n      mengelola akun peserta, memverifikasi data pengusulan, menyusun roadmap kebutuhan,\n      menerbitkan data penetapan, serta menjaga keamanan sesi kerja sehari-hari.</div>\n    <div class=\"cov-chips\">\n      <span class=\"cov-chip\">14 Bab Panduan</span>\n      <span class=\"cov-chip\">Matriks Hak Akses</span>\n      <span class=\"cov-chip\">SOP &amp; Troubleshooting</span>\n    </div>\n    <div class=\"cov-meta\"><b>Edisi 2026</b> &middot; Disusun sesuai tampilan Platform SIMBAKES v2.0\n      <span class=\"sub\">Dinas Kesehatan Kab. Kutai Kartanegara</span></div>\n    <div class=\"cov-foot\"><span><b>SIMBAKES</b> &middot; Beasiswa Tematik Bidang Kesehatan</span><span>&copy; 2026</span></div>\n  </div>\n</div>","toc":[{"n":1,"judul":"Tentang Panduan Ini","desc":"Sasaran pembaca, cakupan materi, dan konvensi penanda"},{"n":2,"judul":"Gambaran Sistem & Alur Kerja","desc":"Posisi Panel Admin dalam alur beasiswa dan modulnya"},{"n":3,"judul":"Peran & Hak Akses","desc":"Matriks menu untuk superadmin, operator, admin, dan peserta"},{"n":4,"judul":"Login Admin & Manajemen Sesi","desc":"Masuk sistem, perilaku sesi, logout, dan daftar user baru"},{"n":5,"judul":"Dashboard Monitoring","desc":"Kartu statistik otomatis dan popup detail dari data asal"},{"n":6,"judul":"Data Pengusulan: Menelusuri & Mengelola","desc":"Pencarian, filter, pengurutan, pagination, dan ekspor data"},{"n":7,"judul":"Memverifikasi Pengajuan","desc":"Prosedur pemeriksaan berkas dan pengubahan status"},{"n":8,"judul":"Menambah, Mengubah & Menghapus Data","desc":"Input manual, sunting data, dan penghapusan terkontrol"},{"n":9,"judul":"Data Roadmap","desc":"Mengelola kebutuhan, kuota, dan unit pendayaguna"},{"n":10,"judul":"Data Penetapan","desc":"Menerbitkan hasil penerima dan menjaga keakuratannya"},{"n":11,"judul":"Data Akun Peserta","desc":"Menyetujui, menangguhkan, dan mengelola akun peserta"},{"n":12,"judul":"Prosedur Operasional Harian","desc":"Checklist harian dan mingguan tim SIMBAKES"},{"n":13,"judul":"Pemecahan Masalah Umum","desc":"Gejala, penyebab, dan solusi kendala teknis rutin"},{"n":14,"judul":"Keamanan & Praktik Terbaik","desc":"Menjaga kerahasiaan akun dan data pribadi peserta"}],"bab":[{"n":1,"judul":"Tentang Panduan Ini","html":"<div class=\"chapter-header first\">\n    <div class=\"ch-tag\">Bab 01</div>\n    <div class=\"ch-title\">Tentang Panduan Ini</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Buku panduan resmi bagi tim pengelola platform SIMBAKES di Dinas Kesehatan.</p>\n  <p>Buku ini ditulis untuk <b>superadmin, operator, dan admin</b> yang diberi kewenangan\n  mengelola SIMBAKES &mdash; Sistem Informasi Manajemen Beasiswa Tematik Bidang Kesehatan\n  Kabupaten Kutai Kartanegara. Seluruh prosedur di dalamnya mengikuti tampilan dan urutan menu\n  persis seperti di platform, sehingga dapat dipakai sebagai acuan kerja sehari-hari sekaligus\n  rujukan ketika ada petugas baru yang perlu diberi pelatihan singkat.</p>\n  <p>Materi disusun mengikuti tanggung jawab administrasi: mengelola sesi dan akun, memantau\n  dashboard, menelusuri dan memverifikasi data pengusulan, memelihara roadmap kebutuhan,\n  menerbitkan data penetapan, mengelola akun peserta, hingga menjaga keamanan data. Bab\n  <i>Prosedur Operasional Harian</i> merangkum semuanya menjadi checklist praktis, dan bab\n  <i>Pemecahan Masalah Umum</i> menyiapkan Anda menghadapi kendala teknis yang paling sering\n  muncul tanpa harus menunggu bantuan teknis.</p>\n  <p>Untuk panduan sisi peserta (pendaftaran akun, pengisian formulir, cek status), gunakan buku\n  pasangan <i>Panduan Penggunaan untuk Peserta</i>. Ketika peserta menghubungi Anda dengan\n  pertanyaan dasar, Anda dapat merujuk buku tersebut agar jawaban konsisten dengan petunjuk\n  yang mereka terima.</p>\n  <h3 class=\"sec\">Konvensi Penanda</h3>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips</span>\n    <p>Saran kerja yang mempercepat dan merapikan proses, misalnya urutan pemeriksaan berkas.</p></div>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting</span>\n    <p>Wajib diperhatikan demi keakuratan data dan pelayanan peserta.</p></div>\n  <div class=\"callout danger\"><span class=\"co-label\">Hati-hati</span>\n    <p>Tindakan berdampak permanen, seperti menghapus data pengusulan atau akun peserta.</p></div>\n  <p>Istilah bersorotan seperti <span class=\"hl\">Data Pengusulan</span> atau\n  <span class=\"hl\">Ubah Status</span> adalah nama menu dan tombol persis seperti yang tampil di\n  layar. Bila tampilan platform diperbarui, gunakan nama yang paling mendekati dan laporkan\n  perubahan penting kepada pengelola dokumen agar buku ini ikut disesuaikan.</p>"},{"n":2,"judul":"Gambaran Sistem & Alur Kerja","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 02</div>\n    <div class=\"ch-title\">Gambaran Sistem &amp; Alur Kerja</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Memahami posisi Panel Admin dalam alur beasiswa sebelum masuk ke prosedur teknis.</p>\n  <p>SIMBAKES melayani dua kelompok pengguna. <b>Peserta</b> mendaftarkan akun, mengisi formulir\n  ajukan rekomendasi, dan memantau statusnya. <b>Tim admin Dinas Kesehatan</b> berada di belakang\n  layar: menyetujui akun, memverifikasi berkas, memutakhirkan roadmap kebutuhan, dan menerbitkan\n  penetapan penerima. Mutu layanan peserta sangat bergantung pada kecepatan dan ketelitian kerja\n  di sisi admin; setiap status yang Anda tetapkan langsung terlihat oleh peserta di portalnya.</p>\n  <h3 class=\"sec\">Alur Besar Data</h3>\n  <div class=\"flow\">\n    <div class=\"fstep\"><div class=\"fn\">JALUR PESERTA</div><div class=\"ft\">Daftar &amp; Ajukan</div><div class=\"fd\">Peserta membuat akun, login, lalu mengirim formulir beserta foto dan dokumen PDF.</div></div>\n    <div class=\"fstep\"><div class=\"fn\">JALUR ADMIN 1</div><div class=\"ft\">Kelola &amp; Verifikasi</div><div class=\"fd\">Menyetujui akun, memeriksa kelengkapan berkas, menetapkan status pengajuan.</div></div>\n    <div class=\"fstep\"><div class=\"fn\">JALUR ADMIN 2</div><div class=\"ft\">Roadmap &amp; Kuota</div><div class=\"fd\">Memelihara daftar jurusan, kuota, perguruan tinggi, dan unit pendayaguna.</div></div>\n    <div class=\"fstep\"><div class=\"fn\">JALUR ADMIN 3</div><div class=\"ft\">Penetapan</div><div class=\"fd\">Menerbitkan data penerima: status kelulusan, SK, dan data akademik.</div></div>\n  </div>\n  <h3 class=\"sec\">Modul Panel Admin</h3>\n  <p>Setelah login, Panel Admin menyediakan empat modul data dan satu halaman monitoring:</p>\n  <div class=\"cards3\">\n    <div class=\"mcard\"><div class=\"mc-ico\">D</div>\n      <div class=\"mc-t\">Dashboard</div>\n      <div class=\"mc-d\">Ringkasan angka seluruh pengajuan per status, terbarui otomatis tanpa tombol refresh.</div></div>\n    <div class=\"mcard\"><div class=\"mc-ico\">P</div>\n      <div class=\"mc-t\">Data Pengusulan</div>\n      <div class=\"mc-d\">Seluruh pengajuan peserta: pencarian, filter, detail berkas, foto, dan pengubahan status.</div></div>\n    <div class=\"mcard\"><div class=\"mc-ico\">R</div>\n      <div class=\"mc-t\">Data Roadmap</div>\n      <div class=\"mc-d\">Kebutuhan beasiswa per jurusan: kuota, perguruan tinggi, tahun studi, dan statusnya.</div></div>\n    <div class=\"mcard\"><div class=\"mc-ico\">T</div>\n      <div class=\"mc-t\">Data Penetapan</div>\n      <div class=\"mc-d\">Daftar penerima yang diterbitkan untuk ditampilkan pada Cek Status Penetapan peserta.</div></div>\n    <div class=\"mcard\"><div class=\"mc-ico\">A</div>\n      <div class=\"mc-t\">Data Akun Peserta</div>\n      <div class=\"mc-d\">Kelola akun: setujui pendaftar baru, tangguhkan, sunting, atau hapus.</div></div>\n    <div class=\"mcard\"><div class=\"mc-ico\">E</div>\n      <div class=\"mc-t\">Ekspor Data</div>\n      <div class=\"mc-d\">Setiap modul data menyediakan tombol unduh untuk kebutuhan pelaporan dan arsip.</div></div>\n  </div>\n  <div class=\"callout info\"><span class=\"co-label\">Catatan</span>\n    <p>Menu yang tampil pada Panel Admin menyesuaikan peran Anda (Bab 3). Bila suatu menu tidak\n    muncul, akun Anda memang tidak memegang kewenangan tersebut &mdash; bukan kesalahan sistem.</p></div>"},{"n":3,"judul":"Peran & Hak Akses","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 03</div>\n    <div class=\"ch-title\">Peran &amp; Hak Akses</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Sistem menerapkan kendali akses berbasis peran (role-based access control).</p>\n  <p>Setiap akun Panel Admin membawa satu peran yang menentukan menu mana yang terbuka. Pembagian\n  ini menjaga prinsip <i>least privilege</i>: petugas hanya melihat data yang ia perlukan, sehingga\n  risiko salah ubah berkurang dan jejak kerja lebih mudah ditelusuri. Saat login berhasil, peran\n  akun tampil sebagai lencana pada bilah info admin di menu samping (mis. SUPERADMIN atau OPERATOR).</p>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:150px\">Peran</th><th>Menu yang Dapat Diakses</th></tr></thead>\n    <tbody>\n      <tr><td><span class=\"badge b-verify\">Superadmin</span></td>\n        <td>Seluruh menu: Dashboard, Data Pengusulan, Data Roadmap, Data Penetapan, Data Akun Peserta, plus manajemen user dan pengaturan.</td></tr>\n      <tr><td><span class=\"badge b-ok\">Operator</span></td>\n        <td><b>Data Pengusulan</b> dan <b>Data Akun Peserta</b> &mdash; fokus pada verifikasi berkas dan pengelolaan akun peserta.</td></tr>\n      <tr><td><span class=\"badge b-rev\">Admin / Viewer</span></td>\n        <td><b>Dashboard</b>, <b>Data Roadmap</b>, dan <b>Data Penetapan</b> &mdash; fokus pada monitoring, kebutuhan, dan hasil penetapan.</td></tr>\n      <tr><td><span class=\"badge b-off\">Peserta</span></td>\n        <td>Portal layanan peserta saja (Ajukan Rekomendasi, Cek Status, Cek Penetapan); tidak memiliki akses Panel Admin.</td></tr>\n    </tbody>\n  </table>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting</span>\n    <p>Berikan peran sesuai kewenangan riil petugas. Operator seharusnya tidak memegang akun\n    superadmin \"untuk jaga-jaga\"; akun dengan kewenangan luas yang tidak terpakai adalah\n    celah keamanan yang paling sering diabaikan.</p></div>\n  <h3 class=\"sec\">Membuat Akun Panel Admin Baru</h3>\n  <p>Superadmin mendaftarkan petugas baru melalui tombol <span class=\"hl\">Daftar User Baru</span>\n  pada bagian Panel Admin (tampil sebelum login). Isi nama pengguna, password, dan peran yang\n  diberikan, lalu serahkan kredensial kepada petugas melalui jalur pribadi &mdash; bukan grup\n  bersama. Pastikan petugas mengganti kebiasaan menyimpan password di tempat terbuka (Bab 14).</p>"},{"n":4,"judul":"Login Admin & Manajemen Sesi","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 04</div>\n    <div class=\"ch-title\">Login Admin &amp; Manajemen Sesi</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Masuk ke Panel Admin dan pahami perilaku sesi agar pekerjaan tidak hilang.</p>\n  <p>Login admin dilakukan dari form <b>Panel Admin</b> di bagian bawah menu samping &mdash;\n  berbeda dengan login peserta yang muncul sebagai jendela tersendiri. Setelah berhasil, form\n  berganti menjadi bilah info berisi nama, lencana peran, dan status sesi, lalu menu admin yang\n  tersedia untuk peran Anda akan tampil di bawahnya.</p>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Gulung menu samping ke bagian Panel Admin.</b>\n      <p>Form berisi kolom Username dan Password serta tombol <span class=\"hl\">Login Admin</span>.</p></li>\n    <li><b class=\"st\">Masukkan username dan password admin.</b>\n      <p>Perhatikan huruf kapital; username bersifat case-sensitive sesuai yang terdaftar.</p></li>\n    <li><b class=\"st\">Klik <span class=\"hl\">Login Admin</span>.</b>\n      <p>Bilah info admin muncul dengan lencana peran (SUPERADMIN / OPERATOR / ADMIN), dan menu\n      modul sesuai peran tampil di bawahnya.</p></li>\n    <li><b class=\"st\">Buka modul yang diperlukan dari menu samping.</b>\n      <p>Misalnya <span class=\"hl\">Data Pengusulan</span> untuk memulai verifikasi harian.</p></li>\n  </ol>\n  <h3 class=\"sec\">Perilaku Sesi</h3>\n  <ul class=\"plain\">\n    <li><b>Tahan refresh.</b> Sesi admin tetap hidup ketika halaman dimuat ulang; menu admin dipulihkan otomatis tanpa login ulang.</li>\n    <li><b>Idle timeout 15 menit.</b> Bila perangkat ditinggalkan tanpa aktivitas, sesi diakhiri otomatis demi keamanan; login kembali untuk melanjutkan.</li>\n    <li><b>Logout bersih.</b> Klik <span class=\"hl\">Logout</span> di bagian Panel Admin setelah selesai bekerja, terutama pada komputer yang dipakai bersama.</li>\n  </ul>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips</span>\n    <p>Selesaikan satu blok pekerjaan verifikasi sebelum beranjak, lalu logout. Data yang sudah\n    tersimpan aman di server; yang berisiko hilang hanyalah isian form yang belum dikirim.</p></div>\n  <div class=\"callout danger\"><span class=\"co-label\">Hati-hati</span>\n    <p>Jangan tinggalkan sesi admin terbuka pada komputer layanan yang dapat diakses pengunjung.\n    Idle timeout membantu, tetapi kebiasaan logout manual tetap lini pertama keamanan.</p></div>"},{"n":5,"judul":"Dashboard Monitoring","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 05</div>\n    <div class=\"ch-title\">Dashboard Monitoring</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Satu layar untuk memahami kondisi seluruh pengajuan dalam angka.</p>\n  <p>Dashboard adalah halaman pembuka SIMBAKES dan menjadi titik awal pemantauan harian. Kartu\n  statistik menampilkan angka utama: <b>Jumlah Usulan</b> (total seluruh data),\n  <b>Disetujui</b>, <b>Ditolak</b>, <b>Perbaikan</b>, dan <b>Batal</b>, disusul kartu akademik\n  seperti jumlah lulus tes masuk PT, jurusan, dan unit. Setiap kartu dirancang ringkas dengan\n  judul dan angka saja, sehingga kondisi program dapat dibaca dalam beberapa detik.</p>\n  <p>Data dashboard dimuat <b>otomatis saat halaman terbuka</b> &mdash; Anda tidak perlu menekan\n  tombol refresh untuk melihat angka terkini. Tombol <span class=\"hl\">Refresh</span> tetap\n  tersedia untuk memaksa pembaruan manual bila Anda ingin memastikan angka terbaru setelah\n  tim lain memasukkan data.</p>\n  <h3 class=\"sec\">Popup Detail dari Data Asal</h3>\n  <p>Klik kartu mana pun untuk membuka popup berisi rincian data sesuai kartu tersebut. Popup\n  mengambil data langsung dari sumber asalnya di database &mdash; bukan salinan &mdash; sehingga\n  selalu akurat. Tiap baris menampilkan <b>foto peserta</b> beserta data pokoknya, dan daftar\n  dapat ditelusuri lebih jauh tanpa meninggalkan halaman dashboard. Ini memudahkan Anda\n  menjawab pertanyaan cepat seperti \"siapa saja yang berstatus Perbaikan hari ini\" tanpa\n  membuka modul data satu per satu.</p>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:200px\">Kartu</th><th>Isi Popup</th></tr></thead>\n    <tbody>\n      <tr><td>Jumlah Usulan</td><td>Seluruh pengajuan yang pernah masuk, tanpa filter status.</td></tr>\n      <tr><td>Disetujui / Ditolak / Perbaikan / Batal</td><td>Hanya pengajuan dengan status kartu tersebut, lengkap dengan foto dan data pokok tiap baris.</td></tr>\n      <tr><td>Kartu akademik</td><td>Ringkasan lulus tes masuk PT, sebaran jurusan, dan unit pemanfaatan.</td></tr>\n    </tbody>\n  </table>\n  <div class=\"callout info\"><span class=\"co-label\">Catatan</span>\n    <p>Angka dashboard dihitung dari seluruh variasi status yang pernah dipakai sistem. Bila\n    sebuah pengajuan tampak \"hilang\" dari satu kartu, periksa kartu lain &mdash; statusnya\n    mungkin berpindah.</p></div>"},{"n":6,"judul":"Data Pengusulan: Menelusuri & Mengelola","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 06</div>\n    <div class=\"ch-title\">Data Pengusulan: Menelusuri &amp; Mengelola</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Modul utama untuk menemukan, memeriksa, dan memproses setiap pengajuan.</p>\n  <p>Menu <span class=\"hl\">Data Pengusulan</span> membuka tabel seluruh pengajuan dengan kolom\n  NIK, Nama Lengkap (disertai avatar foto), Jurusan Tujuan, Rencana Tahun Studi, dan Unit\n  Penempatan. Bilah statistik di atasnya merangkum lima angka: Total Data, Disetujui, Ditolak,\n  Perbaikan, dan Verifikasi. Kombinasi keduanya memberi gambaran cepat sekaligus pintu masuk\n  ke detail setiap berkas.</p>\n  <h3 class=\"sec\">Menelusuri Data</h3>\n  <ul class=\"plain\">\n    <li><b>Kotak pencarian</b>: ketik NIK, nama, nomor register, atau email; hasil disaring saat Anda mengetik.</li>\n    <li><b>Filter status</b>: tampilkan hanya Proses Verifikasi, Disetujui, Ditolak, Perbaikan, atau Batal.</li>\n    <li><b>Pengurutan</b>: urutkan berdasarkan tanggal, nama, NIK, nomor register, atau status; pilih arah terbaru/terlama.</li>\n    <li><b>Pagination</b>: atur tampilan 10/25/50/100 baris per halaman untuk kecepatan muat terbaik.</li>\n    <li><b>Test Koneksi</b>: tombol pemriksaan cepat ke server bila data terasa lambat tampil.</li>\n  </ul>\n  <h3 class=\"sec\">Membuka Detail Peserta</h3>\n  <p>Klik baris peserta untuk membuka kartu data lengkap: foto pasfoto, seluruh isian formulir\n  (data pribadi, pekerjaan, rencana studi, kontak), status terkini, dan tautan dokumen PDF yang\n  diunggah peserta. Dari kartu ini pula Anda melakukan verifikasi (Bab 7), sunting, atau\n  pengubahan status. Foto ditampilkan melalui beberapa metode pengambilan bertingkat, sehingga\n  umumnya selalu tampil; bila satu metode gagal, sistem otomatis mencoba jalur berikutnya.</p>\n  <h3 class=\"sec\">Ekspor Data</h3>\n  <p>Tombol <span class=\"hl\">Export Data</span> mengunduh seluruh data pengusulan ke berkas yang\n  siap dibuka di aplikasi lembar kerja. Gunakan untuk laporan berkala, arsip periode, atau\n  bahan rekap rapat. Ekspor mengambil data langsung dari server, bukan hanya halaman yang sedang\n  tampil, sehingga cakupannya selalu lengkap.</p>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips</span>\n    <p>Awali sesi verifikasi dengan filter status <span class=\"badge b-verify\">Proses Verifikasi</span>\n    diurutkan dari tanggal terlama agar berkas tidak menumpuk dan peserta terlama tidak terlewat.</p></div>"},{"n":7,"judul":"Memverifikasi Pengajuan","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 07</div>\n    <div class=\"ch-title\">Memverifikasi Pengajuan</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Prosedur inti yang menentukan mutu program: memeriksa dan memutuskan tiap berkas.</p>\n  <p>Verifikasi dilakukan dari kartu detail peserta pada <span class=\"hl\">Data Pengusulan</span>.\n  Tujuan Anda memastikan dua hal: data formulir konsisten dengan dokumen pendukung, dan dokumen\n  memenuhi ketentuan program. Keputusan Anda kemudian ditetapkan melalui tombol\n  <span class=\"hl\">Ubah Status</span> pada kartu detail, lalu <span class=\"hl\">Simpan Perubahan</span>.</p>\n  <h3 class=\"sec\">Langkah Pemeriksaan</h3>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Bandingkan data pribadi dengan KTP dan KK.</b>\n      <p>Cocokkan NIK (16 digit), nama lengkap, tempat/tanggal lahir, dan alamat.</p></li>\n    <li><b class=\"st\">Periksa dokumen PDF kelengkapan.</b>\n      <p>Buka tautan dokumen: pastikan keenam berkas ada sesuai urutan (KTP, KK, Ijazah/SKL,\n      Transkrip, STR bila ada, Surat Permohonan &amp; Kesediaan) dan terbaca jelas.</p></li>\n    <li><b class=\"st\">Periksa foto pasfoto.</b>\n      <p>Format JPG/PNG, 4&times;6 cm, latar merah, wajah jelas. Foto tampil di kartu detail dan\n      popup dashboard.</p></li>\n    <li><b class=\"st\">Periksa surat pernyataan bertanda tangan.</b>\n      <p>Surat tanpa tanda tangan dianggap tidak lengkap.</p></li>\n    <li><b class=\"st\">Nilai narasi dan kesesuaian jurusan dengan roadmap.</b>\n      <p>Jurusan tujuan idealnya tersedia pada Data Roadmap dengan sisa kuota.</p></li>\n    <li><b class=\"st\">Tetapkan status dan simpan.</b>\n      <p>Pilih keputusan pada <span class=\"hl\">Ubah Status</span>, isi alasan bila diminta, lalu simpan.</p></li>\n  </ol>\n  <h3 class=\"sec\">Makna Keputusan dan Dampaknya bagi Peserta</h3>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:170px\">Status</th><th>Kapan Digunakan</th><th style=\"width:220px\">Yang Terlihat Peserta</th></tr></thead>\n    <tbody>\n      <tr><td><span class=\"badge b-verify\">Proses Verifikasi</span></td><td>Berkas sedang diantri/diperiksa; juga dipakai ulang setelah peserta merevisi.</td><td>Status berjalan, tidak perlu tindakan.</td></tr>\n      <tr><td><span class=\"badge b-ok\">Disetujui</span></td><td>Seluruh berkas lengkap dan memenuhi syarat; layak masuk penetapan.</td><td>Pengumuman lolos seleksi berkas.</td></tr>\n      <tr><td><span class=\"badge b-no\">Ditolak</span></td><td>Tidak memenuhi persyaratan program secara substansial.</td><td>Status ditolak beserta alasan.</td></tr>\n      <tr><td><span class=\"badge b-rev\">Perbaikan</span></td><td>Ada kekurangan yang dapat diperbaiki: dokumen kabur, data tidak cocok, surat tidak bertanda tangan.</td><td>Form perbaikan data terbuka di portalnya.</td></tr>\n      <tr><td><span class=\"badge b-off\">Batal</span></td><td>Pengajuan ditarik atau digantikan sesuai keputusan program.</td><td>Status batal pada kartunya.</td></tr>\n    </tbody>\n  </table>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting</span>\n    <p>Gunakan <span class=\"badge b-rev\">Perbaikan</span> (bukan <span class=\"badge b-no\">Ditolak</span>)\n    untuk kekurangan yang masih dapat diperbaiki. Setelah peserta menyimpan revisi, statusnya\n    otomatis kembali ke <span class=\"badge b-verify\">Proses Verifikasi</span> dan Anda memeriksa ulang.</p></div>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips</span>\n    <p>Catat alasan yang spesifik saat meminta perbaikan, misalnya \"transkrip halaman 2 tidak\n    terbaca &mdash; mohon pindai ulang\". Instruksi jelas mempercepat revisi dan mengurangi\n    pertanyaan bolak-balik.</p></div>"},{"n":8,"judul":"Menambah, Mengubah & Menghapus Data Pengusulan","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 08</div>\n    <div class=\"ch-title\">Menambah, Mengubah &amp; Menghapus Data Pengusulan</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Alat koreksi data untuk kondisi yang tidak dapat diselesaikan oleh peserta.</p>\n  <h3 class=\"sec\">Menambah Data Manual</h3>\n  <p>Tombol <span class=\"hl\">Tambah Data</span> pada halaman Data Pengusulan membuka form isian\n  lengkap. Gunakan untuk pendampingan luring &mdash; misalnya peserta yang datang ke kantor dan\n  kesulitan mengisi formulir sendiri, atau registrasi hasil layanan lapangan yang perlu\n  dimasukkan petugas. Isi seluruh kolom sesuai dokumen fisik yang Anda pegang, unggah foto dan\n  dokumen yang telah dipindai, lalu simpan. Pengajuan yang masuk lewat jalur ini diperlakukan\n  sama dengan pengajuan mandiri peserta.</p>\n  <h3 class=\"sec\">Mengubah Data</h3>\n  <p>Dari kartu detail, pilih menu sunting untuk mengoreksi isian &mdash; misalnya salah ketik\n  nama, unit penempatan yang keliru, atau pembaruan kontak. Perbaikan administratif oleh admin\n  tidak mengubah status pengajuan; gunakan <span class=\"hl\">Ubah Status</span> secara terpisah\n  bila keputusan ikut berubah. Catat setiap koreksi besar pada log kerja tim agar mudah ditelusuri.</p>\n  <h3 class=\"sec\">Menghapus Data</h3>\n  <p>Penghapusan tersedia untuk data ganda atau pengajuan tidak sah. Sistem meminta konfirmasi\n  sebelum mengeksekusi, namun konfirmasi itu bukan pengaman penuh: <b>data yang terhapus tidak\n  dapat dikembalikan dari antarmuka</b>.</p>\n  <div class=\"callout danger\"><span class=\"co-label\">Hati-hati</span>\n    <p>Sebelum menghapus, pastikan data tersebut benar duplikat atau tidak sah &mdash; bukan\n    sekadar salah status. Untuk pengajuan yang batal, gunakan status\n    <span class=\"badge b-off\">Batal</span> agar riwayat tetap terjaga untuk pelaporan.</p></div>"},{"n":9,"judul":"Data Roadmap","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 09</div>\n    <div class=\"ch-title\">Data Roadmap</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Sumber kebenaran bagi jurusan, kuota, dan unit pendayaguna yang dilihat peserta.</p>\n  <p><span class=\"hl\">Data Roadmap</span> memuat kebutuhan beasiswa per bidang: jurusan,\n  kualifikasi awal, jenis pendidikan, perguruan tinggi, pekerjaan yang diprioritaskan, tahun\n  studi, jumlah kuota, kuota terisi, sisa kuota, unit pendayaguna, status, dan nama penerima.\n  Data ini menjadi acuan peserta memilih jurusan pada formulir pendaftaran akun dan ajukan\n  rekomendasi, sehingga kerapian roadmap berdampak langsung pada mutu pengajuan yang masuk.</p>\n  <h3 class=\"sec\">Mengelola Baris Roadmap</h3>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Klik <span class=\"hl\">Tambah Data Baru</span> untuk membuka form isian.</b>\n      <p>Pilih jurusan, kualifikasi awal, jenis pendidikan, dan perguruan tinggi tujuan; tetapkan\n      pekerjaan prioritas, tahun studi, jumlah kuota, serta unit pendayaguna.</p></li>\n    <li><b class=\"st\">Tetapkan status baris tersebut.</b>\n      <p><span class=\"badge b-ok\">Aktif</span> membuka kuota bagi pendaftar;\n      <span class=\"badge b-rev\">Pending</span> menunda;\n      <span class=\"badge b-off\">Non-Aktif</span> menutup;\n      <span class=\"badge b-verify\">Selesai</span> menandai kuota terpenuhi.</p></li>\n    <li><b class=\"st\">Mutakhirkan kuota terisi secara berkala.</b>\n      <p>Setiap kali penetapan diterbitkan, naikkan kuota terisi agar sisa kuota yang dilihat\n      peserta tetap akurat.</p></li>\n    <li><b class=\"st\">Gunakan pencarian dan filter status untuk pemeliharaan cepat.</b>\n      <p>Tombol <span class=\"hl\">Export Data</span> tersedia untuk arsip dan laporan.</p></li>\n  </ol>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting</span>\n    <p>Perubahan roadmap langsung memengaruhi pilihan yang tersedia bagi calon pendaftar.\n    Koordinasikan penutupan/pembukaan jurusan dengan kepemimpinan program sebelum menyimpan,\n    agar tidak ada peserta yang mendaftar pada jurusan yang kebetulan sedang diperbarui.</p></div>"},{"n":10,"judul":"Data Penetapan","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 10</div>\n    <div class=\"ch-title\">Data Penetapan</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Modul penerbitan hasil akhir: penerima, SK, dan data akademiknya.</p>\n  <p><span class=\"hl\">Data Penetapan</span> berisi daftar penerima beasiswa yang diterbitkan\n  Dinas Kesehatan. Data pada modul inilah yang tampil kepada peserta ketika mereka membuka\n  <span class=\"hl\">Cek Status Penetapan</span> dengan NIK mereka: foto penerima, nomor register,\n  nama, NIK, status kelulusan, serta data akademik (jurusan, jenjang, perguruan tinggi, unit\n  kerja). Karena itu, keakuratan dan kelengkapan setiap baris wajib diperiksa sebelum\n  dipublikasikan.</p>\n  <h3 class=\"sec\">Membaca dan Menelusuri</h3>\n  <ul class=\"plain\">\n    <li><b>Bilah statistik</b>: Total Data, Lulus, Pending, dan Ditolak &mdash; memberi gambaran cepat hasil penetapan.</li>\n    <li><b>Pencarian</b>: cari berdasarkan nama, NIK, atau jurusan.</li>\n    <li><b>Filter</b>: saring menurut status (Lulus, Pending, Ditolak, Dalam Proses) dan jurusan.</li>\n    <li><b>Tabel</b>: kolom nomor, foto, nama, NIK, jurusan, jenjang, perguruan tinggi, unit kerja, status, dan aksi; dukungan pagination untuk daftar panjang.</li>\n    <li><b>Export</b>: unduh seluruh data penetapan untuk dokumen pelaporan resmi.</li>\n  </ul>\n  <h3 class=\"sec\">Status Penetapan</h3>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:170px\">Status</th><th>Makna dan Penggunaannya</th></tr></thead>\n    <tbody>\n      <tr><td><span class=\"badge b-ok\">Lulus</span></td><td>Peserta ditetapkan sebagai penerima; kartu penetapannya lengkap dengan SK dan data akademik.</td></tr>\n      <tr><td><span class=\"badge b-rev\">Pending</span></td><td>Data penetapan sedang disiapkan/menunggu kelengkapan dokumen keputusan.</td></tr>\n      <tr><td><span class=\"badge b-verify\">Dalam Proses</span></td><td>Sedang berjalan pada gelombang saat ini; akan diperbarui menjadi status akhir.</td></tr>\n      <tr><td><span class=\"badge b-no\">Ditolak</span></td><td>Usulan tidak ditetapkan pada periode ini; peserta dapat mengikuti periode berikutnya sesuai ketentuan.</td></tr>\n    </tbody>\n  </table>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting</span>\n    <p>Publikasikan penetapan hanya untuk pengajuan yang berstatus\n    <span class=\"badge b-ok\">Disetujui</span> pada Data Pengusulan. Selalu unggah/tautkan foto\n    dan lengkapi data akademik agar kartu yang dilihat peserta tampil utuh dan resmi.</p></div>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips</span>\n    <p>Setelah menerbitkan satu gelombang, beri tahu PIC layanan agar siap menjawab lonjakan\n    pertanyaan peserta, dan pastikan sisa kuota pada Data Roadmap ikut diperbarui (Bab 9).</p></div>"},{"n":11,"judul":"Data Akun Peserta","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 11</div>\n    <div class=\"ch-title\">Data Akun Peserta</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Gerbang pertama layanan: menyetujui dan memelihara akun para peserta.</p>\n  <p><span class=\"hl\">Data Akun Peserta</span> mengelola tabel akun: tambah, ubah, setujui,\n  tangguhkan, dan hapus. Bilah statistiknya merangkum Total Akun, Disetujui, Menunggu, serta\n  Ditolak/Ditangguhkan. Tabel menampilkan nama lengkap, akun login, jurusan tujuan, status,\n  login terakhir, dan kolom aksi. Akun yang baru mendaftar lewat halaman pendaftaran masuk\n  sebagai <span class=\"badge b-rev\">Menunggu Persetujuan</span> dan baru dapat login setelah\n  Anda menyetujuinya.</p>\n  <h3 class=\"sec\">Menyetujui Pendaftar Baru</h3>\n  <ol class=\"steps\">\n    <li><b class=\"st\">Saring status <span class=\"badge b-rev\">Menunggu Persetujuan</span>.</b>\n      <p>Gunakan filter status dan urutkan dari tanggal terlama agar tidak ada pendaftar terlupakan.</p></li>\n    <li><b class=\"st\">Periksa kewajaran data pendaftar.</b>\n      <p>Nama sesuai identitas, NIK 16 digit, email aktif, jurusan tujuan tersedia pada roadmap.</p></li>\n    <li><b class=\"st\">Setujui akun yang memenuhi syarat.</b>\n      <p>Peserta langsung dapat login ke portal; beri tahu mereka lewat jalur resmi bila perlu.</p></li>\n    <li><b class=\"st\">Tolak atau tangguhkan bila diperlukan.</b>\n      <p>Gunakan untuk akun ganda, data tidak sah, atau menunggu klarifikasi; akun tertangguh\n      dapat dibuka kembali setelah masalah selesai.</p></li>\n  </ol>\n  <h3 class=\"sec\">Pengelolaan Lanjutan</h3>\n  <ul class=\"plain\">\n    <li><b>Tambah Akun</b>: buatkan akun secara manual untuk peserta binaan yang tidak dapat mendaftar mandiri; bagikan kredensial melalui jalur pribadi.</li>\n    <li><b>Sunting</b>: koreksi nama, email, jurusan tujuan, atau reset kredensial atas permintaan sah pemilik akun.</li>\n    <li><b>Hapus</b>: hanya untuk akun ganda/spam &mdash; tindakan permanen.</li>\n    <li><b>Login Terakhir</b>: petunjuk akun yang jarang dipakai; bermanfaat saat membereskan daftar sebelum penetapan.</li>\n  </ul>\n  <div class=\"callout warn\"><span class=\"co-label\">Penting</span>\n    <p>Satu NIK satu akun. Bila ditemukan pendaftaran ganda, setujui satu yang datanya paling\n    lengkap dan tangguhkan sisanya; jangan menghapus duanya sebelum yakin mana yang dipakai\n    peserta.</p></div>"},{"n":12,"judul":"Prosedur Operasional Harian","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 12</div>\n    <div class=\"ch-title\">Prosedur Operasional Harian</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Checklist rutin agar layanan tetap cepat dan tidak ada berkas yang tertahan.</p>\n  <p>Konsistensi harian lebih menentukan kepuasan peserta daripada kecepatan sesaat. Checklist\n  berikut dirancang untuk sesi kerja admin yang berlangsung 30&ndash;60 menit setiap hari kerja.\n  Sesuaikan pembagiannya dengan peran Anda: operator berfokus pada poin verifikasi dan akun,\n  sedangkan admin penetapan berfokus pada roadmap dan publikasi hasil.</p>\n  <h3 class=\"sec\">Checklist Harian</h3>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:38px\">No</th><th style=\"width:250px\">Aktivitas</th><th>Rincian</th></tr></thead>\n    <tbody>\n      <tr><td>1</td><td>Setujui akun yang menunggu</td><td>Saring status Menunggu di Data Akun Peserta; proses pendaftar terlama lebih dulu (target 1&ndash;2 hari kerja).</td></tr>\n      <tr><td>2</td><td>Verifikasi pengajuan baru</td><td>Buka Data Pengusulan dengan filter Proses Verifikasi, urut terlama; periksa sesuai Bab 7.</td></tr>\n      <tr><td>3</td><td>Proses hasil perbaikan</td><td>Cek pengajuan yang baru direvisi peserta; pastikan kekurangan benar teratasi sebelum keputusan akhir.</td></tr>\n      <tr><td>4</td><td>Monitor dashboard</td><td>Bandingkan angka Disetujui/Perbaikan/Ditolak dengan hari sebelumnya; kejanggalan berarti ada isu.</td></tr>\n      <tr><td>5</td><td>Balas eskalasi PIC</td><td>Tindak lanjuti kendala yang diteruskan PIC: akun, akses dokumen, atau koreksi data darurat.</td></tr>\n    </tbody>\n  </table>\n  <h3 class=\"sec\">Checklist Mingguan</h3>\n  <ul class=\"plain\">\n    <li><b>Rapikan roadmap</b>: perbarui kuota terisi, pindahkan jurusan penuh ke status Selesai, koordinasikan pembukaan kuota baru.</li>\n    <li><b>Siapkan draf penetapan</b>: kumpulkan pengajuan Disetujui yang siap diterbitkan pada gelombang berikutnya.</li>\n    <li><b>Ekspor dan arsipkan</b>: unduh Data Pengusulan dan Data Penetapan untuk arsip mingguan.</li>\n    <li><b>Tinjau akun bermasalah</b>: akun ditangguhkan yang belum selesai, akun ganda, dan percobaan login mencurigakan.</li>\n    <li><b>Evaluasi umur berkas</b>: pengajuan yang menunggu lebih dari satu minggu perlu diprioritaskan atau dieskalasikan.</li>\n  </ul>\n  <div class=\"callout tip\"><span class=\"co-label\">Tips</span>\n    <p>Tandai poin 1&ndash;3 sebagai pekerjaan pagi hari. Peserta yang mencoba login atau\n    memantau status paling banyak pada pagi; sesi yang rapi sebelum tengah hari menekan\n    keluhan sepanjang sore.</p></div>"},{"n":13,"judul":"Pemecahan Masalah Umum","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 13</div>\n    <div class=\"ch-title\">Pemecahan Masalah Umum</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Panduan cepat mengatasi gejala yang paling sering dilaporkan.</p>\n  <p>Sebagian besar kendala harian bermula dari jaringan, sesi, atau file yang diunggah peserta.\n  Tabel berikut merangkum gejala, penyebab yang paling mungkin, dan langkah solusi. Bila solusi\n  pertama tidak berhasil, naikkan ke jalur eskalasi di akhir bab &mdash; jangan mencoba\n  perbaikan di luar prosedur pada data produksi.</p>\n  <table class=\"data\">\n    <thead><tr><th style=\"width:220px\">Gejala</th><th>Solusi Berurutan</th></tr></thead>\n    <tbody>\n      <tr><td>Foto peserta tidak tampil pada tabel/popup</td>\n        <td>Tunggu sejenak (ambil foto bertahap multi-metode), klik Refresh, uji perangkat/jaringan lain, lalu periksa file sumber di penyimpanan. Laporkan bila tetap kosong.</td></tr>\n      <tr><td>Data tidak muncul / tabel terus memuat</td>\n        <td>Klik <span class=\"hl\">Refresh</span> modul; coba <span class=\"hl\">Test Koneksi</span>; muat ulang halaman; pastikan internet stabil.</td></tr>\n      <tr><td>Gagal simpan perubahan status</td>\n        <td>Pastikan sesi masih aktif (bila terlogout, login ulang), lengkapi isian wajib pada form status, lalu ulangi simpan.</td></tr>\n      <tr><td>Peserta tidak dapat login meski akun disetujui</td>\n        <td>Cek status akun di Data Akun Peserta; pastikan bukan Ditangguhkan; periksa ejaan username; reset kredensial bila perlu.</td></tr>\n      <tr><td>Sesi admin terlogout sendiri</td>\n        <td>Perilaku normal setelah 15 menit idle; login ulang. Bila terjadi berulang saat aktif, laporkan sebagai isu teknis.</td></tr>\n      <tr><td>Ekspor tampak kosong/kurang</td>\n        <td>Pastikan tidak ada filter aktif yang disengaja; ekspor mengambil data penuh dari server, bukan tampilan terfilter.</td></tr>\n      <tr><td>Angka dashboard berbeda dengan harapan</td>\n        <td>Ingat popup kartu memakai data asal; cek kartu status lain &mdash; pengajuan mungkin berpindah status setelah verifikasi.</td></tr>\n    </tbody>\n  </table>\n  <h3 class=\"sec\">Eskalasi</h3>\n  <p>Bila kendala tidak teratasi, kumpulkan bukti sebelum melapor: tangkapan layar, nama akun,\n  nomor register terkait, perkiraan waktu kejadian, dan langkah yang sudah dicoba. Sampaikan\n  kepada pengelola teknis platform melalui PIC program (Mukmin Nasri 0821-3027-5800 atau\n  Syarifah Putri 0821-5758-0022). Laporan yang lengkap mempercepat diagnosis dan menghindari\n  pertanyaan bolak-balik.</p>"},{"n":14,"judul":"Keamanan & Praktik Terbaik","html":"<div class=\"chapter-header\">\n    <div class=\"ch-tag\">Bab 14</div>\n    <div class=\"ch-title\">Keamanan &amp; Praktik Terbaik</div>\n    <div class=\"ch-div\"><span class=\"bar\"></span><span class=\"hair\"></span></div>\n  </div>\n  <p class=\"lead\">Anda memegang data pribadi para peserta; kelola dengan standar yang pantas.</p>\n  <p>Panel admin memuat data identitas peserta: NIK, alamat, kontak, dan dokumen pendukung.\n  Perlakukan data tersebut sebagaimana berkas fisik dinas &mdash; hanya diakses petugas\n  berwenang, hanya untuk keperluan program, dan tidak disalin ke perangkat pribadi tanpa dasar\n  resmi. Kebiasaan kecil berikut menjaga sistem tetap aman sekaligus menjaga kepercayaan\n  publik kepada program.</p>\n  <ul class=\"plain\">\n    <li><b>Kredensial pribadi.</b> Password tidak dibagikan, tidak ditempel di meja kerja, dan tidak dikirim melalui grup. Setiap petugas memakai akunnya sendiri agar jejak kerja jelas.</li>\n    <li><b>Peran sesuai kewenangan.</b> Minta peran yang benar saat akun dibuatkan; kembangkan akun superadmin hanya untuk pengelola inti.</li>\n    <li><b>Logout setelah selesai.</b> Terutama pada komputer layanan; andalkan idle timeout sebagai jaring pengaman, bukan kebiasaan utama.</li>\n    <li><b>Verifikasi permintaan perubahan.</b> Reset password atau perubahan data akun hanya untuk permintaan sah pemilik akun yang terverifikasi identitasnya.</li>\n    <li><b>Komunikasi resmi.</b> Informasikan keputusan (persetujuan, perbaikan, penetapan) melalui kanal resmi program; jangan pernah meminta password peserta dalam bentuk apa pun.</li>\n    <li><b>Laporkan insiden segera.</b> Dugaan akses ilegal, akun aneh, atau data bocor dilaporkan hari itu juga kepada pengelola teknis melalui PIC.</li>\n  </ul>\n  <p>Dengan prosedur pada buku ini dijalankan konsisten &mdash; akun diproses cepat, berkas\n  diperiksa teliti, roadmap dijaga akurat, dan penetapan diterbitkan lengkap &mdash; SIMBAKES\n  akan berjalan sebagai satu layanan beasiswa yang cepat, transparan, dan dapat dipertanggung-\n  jawabkan bagi seluruh peserta di Kabupaten Kutai Kartanegara.</p>"}]}$pb$::jsonb;
end;
$fn$;

-- Eksekusi lewat PostgREST memakai role anon (aplikasi tidak memakai
-- Supabase Auth); fungsi tetap aman karena validasi terjadi di dalam.
grant execute on function public.app_get_panduan_admin() to anon, authenticated;

-- Catatan keamanan:
--  * Isi buku TIDAK dibaca lewat tabel publik, hanya lewat fungsi ini.
--  * Tanpa header 'x-session-token' sesi admin/operator yang valid,
--    fungsi mengembalikan null -> PostgREST hanya memberi { "app_get_panduan_admin": null }.
--  * Token sesi berasal dari app_login (SECURITY-HARDENING.sql).
